sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Normaliza os valores removendo espaços extras e convertendo para minúsculas (somente se os campos estiverem preenchidos)
    var formattedName = current.name ? current.name.trim().toLowerCase() : "";
    var formattedCity = current.city ? current.city.trim().toLowerCase() : "";
    var formattedState = current.state_province ? current.state_province.trim().toLowerCase() : "";

    /** ---------------------- ETAPA 1: Verificar Nome ---------------------- **/
    var baseByName = new GlideRecord('x_1546361_bases_bases');
    baseByName.addQuery('name', 'LIKE', formattedName);
    baseByName.query();

    while (baseByName.next()) {
        if (baseByName.name.trim().toLowerCase() === formattedName) {
            gs.addErrorMessage("Já existe uma base cadastrada com esse nome.");
            current.setAbortAction(true);
            return; // Interrompe a execução imediatamente
        }
    }

    /** ----------------- ETAPA 2: Verificar Cidade + Estado ---------------- **/
    if (formattedCity !== "" && formattedState !== "") {  // Só verifica se ambos os campos estão preenchidos
        var baseByLocation = new GlideRecord('x_1546361_bases_bases');
        baseByLocation.addQuery('city', formattedCity);
        baseByLocation.addQuery('state_province', formattedState);
        baseByLocation.query();

        while (baseByLocation.next()) {
            var dbCity = baseByLocation.city ? baseByLocation.city.trim().toLowerCase() : "";
            var dbState = baseByLocation.state_province ? baseByLocation.state_province.trim().toLowerCase() : "";

            if (dbCity === formattedCity && dbState === formattedState) {
                gs.addErrorMessage("Já existe uma base cadastrada na mesma cidade e estado.");
                current.setAbortAction(true);
                return;
            }
        }
    }

    // Atualiza os valores formatados para garantir que sejam salvos corretamente no banco de dados
    current.name = formattedName;
    current.city = formattedCity;
    current.state_province = formattedState;

})(current, previous);
